const $=id=>document.getElementById(id),usd=n=>n.toLocaleString('en-US',{style:'currency',currency:session?.instrument.quote||'USD'}),utc=t=>new Date(t).toISOString().slice(11,19);
let catalog=[],session,source,selected,revision=null,view=60,drawn=-1,settled=false,loading=0,feedbackSignature='',lastOrderClick=0,lastOrderSignature='',briefReturn=null,activeLoad=null;
const wall=createWallClock(performance.now());
function syncNow(force=true){syncWallClock(wall,performance.now(),session,force);}
function setPriceView(next){view=next;priceChart.removeSeries(priceSeries);const precision=Math.log10(session?.account.rules.priceScale||10000),priceFormat={type:'price',precision,minMove:10**-precision};priceSeries=priceChart.addSeries(view==='line'?LC.LineSeries:LC.CandlestickSeries,view==='line'?{color:'#72b1e6',lineType:LC.LineType.WithSteps,priceFormat}:{upColor:'#64b39d',downColor:'#d78174',borderVisible:false,wickUpColor:'#64b39d',wickDownColor:'#d78174',priceFormat});drawn=-1;}
function timingBrief(){if(!selected)return;const timed=$('attemptMode').value==='timed';$('timingHelp').textContent=timed?'Fixed '+(selected.timedSpeed||12)+'× historical clock. No manual pause. Simulated user-order routing: '+(selected.timedRouteDelayMs||6000)/1000+' historical seconds; subsequent observations only.':'Practice allows pause and speed changes. No added route delay; orders still need subsequent source records.';}
const LC=window.LightweightCharts;
const options={autoSize:true,layout:{background:{color:'#15202b'},textColor:'#91a0ae',attributionLogo:true},grid:{vertLines:{color:'#22303d'},horzLines:{color:'#22303d'}},rightPriceScale:{borderColor:'#34414d'},timeScale:{timeVisible:true,secondsVisible:true,borderColor:'#34414d'},localization:{timeFormatter:t=>utc(t*1000)}};
const priceChart=LC.createChart($('priceChart'),options),eqChart=LC.createChart($('equityChart'),options),reviewChart=LC.createChart($('reviewChart'),options);
let priceSeries=priceChart.addSeries(LC.CandlestickSeries,{upColor:'#64b39d',downColor:'#d78174',borderVisible:false,wickUpColor:'#64b39d',wickDownColor:'#d78174'});
const eqSeries=eqChart.addSeries(LC.AreaSeries,{lineColor:'#72b1e6',topColor:'#72b1e630',bottomColor:'#72b1e600',lineWidth:2}),origSeries=reviewChart.addSeries(LC.LineSeries,{color:'#72b1e6',lineWidth:2}),revSeries=reviewChart.addSeries(LC.LineSeries,{color:'#dcb976',lineWidth:2,lineStyle:LC.LineStyle.Dashed});
const points=curve=>{const m=new Map();for(const [t,n]of curve)m.set(t/1000,{time:t/1000,value:n/100});return [...m.values()];};
function setNotice(s){$('notice').textContent=s;}
function draw(){if(!session)return;const a=session.account;
 if(view==='line')priceSeries.setData([...new Map(session.points().map(p=>[p.time,{time:p.time/1000,value:p.p}])).values()]);
 else priceSeries.setData(session.bars(view).map(b=>({time:b.time/1000,open:b.o,high:b.h,low:b.l,close:b.c})));
 eqSeries.setData(points(a.curve));drawn=a.index;
}
function drawReview(){origSeries.setData(points(session.account.curve));revSeries.setData(revision?points(revision.curve):[]);reviewChart.timeScale().fitContent();}
function render(){if(!session)return;const s=session.snapshot(),a=session.account,r=a.rules,c=session.chapter;
 $('symbol').textContent=(c.displaySymbol||c.instrument.symbol+' / '+c.instrument.quote);$('venue').textContent=c.instrument.venue+' · '+c.date+' · '+(r.marketDataKind==='clearing'?'real 5-minute clearing prices':r.marketDataKind==='price'?'original historical price ticks':'historical bid/ask quotes');$('mandate').textContent=c.brief;$('rulesText').textContent=c.brief;$('provenance').textContent=source.rows.length+' retained observations · '+source.sampling+' Source SHA-256 '+source.sourceSha256;
 $('equity').textContent=usd(s.equity);$('cash').textContent=usd(s.cash);$('positionValue').textContent=usd(s.mv);$('fees').textContent=usd(s.fees);$('clock').textContent=utc(s.time);
 const seconds=Math.max(0,Math.ceil((s.deadline-s.time)/1000));$('remaining').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');$('pause').textContent=s.done?'Settled':s.paused?'Resume interrupted run':a.practice.mode==='timed'?'Clock running':'Pause';const started=a.practice.events.some(e=>e.action==='resume');$('pause').disabled=s.done||!started||(a.practice.mode==='timed'&&!s.paused);$('speed').disabled=a.practice.mode==='timed';$('choose').disabled=a.practice.mode==='timed'&&!s.done;$('timingState').textContent=a.practice.mode==='timed'?(a.practice.interrupted?'Timed · interrupted':'Timed · fixed '+a.practice.speed+'×'):'Practice';
 $('missionState').textContent=s.done?(s.outcome.passed?'Mandate met':'Mandate missed'):Math.max(0,s.shares-r.targetUnits)+' '+c.instrument.base+' to reduce';
 $('age').textContent=(s.paused&&!s.done?'Paused · ':'')+(r.marketDataKind==='clearing'?'Latest clearing interval ':r.marketDataKind==='price'?'Last source-price tick ':'Last quote ')+utc(s.observedTime)+' · '+((s.time-s.observedTime)/1000).toFixed(1)+'s old';
 $('bid').textContent=s.bid.toFixed(Math.log10(r.priceScale));$('ask').textContent=s.ask===null?c.instrument.quote+' / '+c.instrument.base+(r.marketDataKind==='price'?' · observed price, side unreported':' · settlement reference'):'Ask '+s.ask.toFixed(Math.log10(r.priceScale))+' '+c.instrument.quote;$('holding').textContent=s.shares+' '+c.instrument.base+(r.intradayBuyLock?' · '+s.sellableShares+' eligible to sell · '+(s.shares-s.sellableShares)+' locked today':'');$('quantityUnit').textContent='Quantity · '+(r.lotSizeUnits===1?'whole ':('lots of '+r.lotSizeUnits+' '))+c.instrument.base;$('quantity').step=String(r.lotSizeUnits);$('quantity').min=String(r.lotSizeUnits);$('equityUnit').textContent=c.instrument.quote+' · fictional starting account';$('lineView').textContent=r.marketDataKind==='clearing'?'Clearing price steps':r.marketDataKind==='price'?'Price tick steps':'Bid line';$('clockLabel').textContent=c.clockLabel||'Historical clock · UTC';$('chartClock').textContent=(c.clockZoneLabel||'UTC')+' · observed prices only';const wallSeconds=Math.max(0,Math.ceil((s.deadline-s.time)/1000/a.practice.speed));$('wallRemaining').textContent=a.practice.mode==='timed'?Math.floor(wallSeconds/60)+':'+String(wallSeconds%60).padStart(2,'0')+' wall time at '+a.practice.speed+'×':'';$('kind').querySelector('[value=stop]').disabled=r.marketDataKind!=='quote';
 $('marketCaption').textContent=r.marketDataKind==='price'?'Original published FX price ticks. Source timezone and bid/ask side are unreported. No missing ticks, spread or volume are fabricated.':r.intradayBuyLock?'Original publisher L1 bid/ask snapshots at their real 2/3/4-second cadence. Snapshot timestamps and quote authenticity have not been independently crosschecked against an exchange feed.':r.marketDataKind==='clearing'?'Actual AEMO five-minute finalized RRP. Interval-ending coordinates are not first-publication times. No quotes or intervening prices are invented.':'Venue-specific bid quotes sampled from genuine updates. Quote gaps retain their real duration. No fabricated ticks or future candles.';
 $('notionalHelp').textContent='Subsequent '+(r.marketDataKind==='clearing'?'clearing observation':r.marketDataKind==='price'?'source-price tick':'eligible quote')+' after '+r.routeDelayMs/1000+' simulated historical seconds. Shared fictional cap '+(r.quoteFillUnits??r.referenceFillUnits)+' '+c.instrument.base+' per source record.';
 $('executionRules').textContent=r.marketDataKind==='price'?'Funded fictional currency exposure at subsequent observed source prices. Bid/ask side, executable spread and traded quantity are unreported. The published numerical compilation has a primary CC BY 4.0 grant; the underlying API feed is not identified. No claim of broker execution or source-clock UTC alignment.':r.intradayBuyLock?'Named 600900.XSHG original L1 prices from the author MIT dataset compilation. Buys use ask; sells and holdings use bid. 100-share lots; inherited shares may sell, newly bought shares stay locked throughout this single-day chapter. 1000-share capacity and routing are fictional; displayed depth is not guaranteed fills. No direct exchange/vendor licensing or independently authenticated feed is claimed. Fees/stamp duty are zero assumptions; auctions, next-day release and price-limit queues are outside this interval.':r.marketDataKind==='clearing'?'Fictional funded cash-settled electricity exposure; no physical inventory, delivery or futures. RRP is a finalized settlement price, not executable bid/ask. APC flag 16 indicates loss-factor scaling and is retained. Shared cap and routing are game assumptions.':'IEX venue quotes, not NBBO. Buys use ask; sells and long marks use bid. Shared per-record caps and route delays are fictional; no queue or market impact is reconstructed.';
 $('sourcePolicy').replaceChildren(document.createTextNode(source.rights.attribution+' '));const policy=document.createElement('a');policy.href=source.rights.terms;policy.target='_blank';policy.rel='noopener';policy.textContent='Source terms';$('sourcePolicy').append(policy);
 for(const b of document.querySelectorAll('[data-view]'))b.disabled=r.marketDataKind!=='quote'&&b.dataset.view!=='line';
 $('position').replaceChildren();for(const text of ['Held',s.shares+' '+session.instrument.base,'Marked value',usd(s.mv),'Average cost',r.marketDataKind==='quote'?usd(s.cost):s.cost.toFixed(Math.log10(r.priceScale))+' '+c.instrument.quote+' / '+c.instrument.base]){const d=document.createElement('span');d.textContent=text;$('position').append(d);}
 $('reviewBtn').disabled=!s.done;$('buy').disabled=s.paused||s.done||$('kind').value==='stop';$('sell').disabled=s.paused||s.done;
 const notional=(Number($('quantity').value)||0)*(s.ask??s.price);$('notional').textContent=Number.isFinite(notional)?usd(notional):'Unsupported amount';
 $('orders').replaceChildren(...a.orders.slice().reverse().map(o=>{const d=document.createElement('div');d.className='order';const h=document.createElement('strong');h.textContent='#'+o.id+' '+o.side.toUpperCase()+' '+o.units+' · '+o.type;const text=document.createElement('span');text.textContent=utc(o.time)+' '+(c.clockZoneLabel||'UTC')+' · '+o.filledUnits+'/'+o.units+' filled · '+decisionStatus(o,a);if(['pending','partial'].includes(o.status)){const left=Math.max(0,((o.eligibleAt??o.time)-s.time)/1000);text.textContent+=' · '+(left>0?'routing '+left.toFixed(1)+' historical seconds':'waiting for subsequent source observation');}d.append(h,text);if(['pending','partial'].includes(o.status)&&!o.automatic&&!s.done){const b=document.createElement('button');b.textContent='Cancel remainder #'+o.id;b.disabled=s.paused;b.onclick=()=>{try{syncNow();session.cancel(o.id);$('orderFeedback').textContent='Order #'+o.id+' remainder cancelled. Completed fills retained.';}catch(e){$('orderFeedback').textContent=e.message;}};d.append(b);}return d;}));
 const recent=a.orders.at(-1),sig=recent?JSON.stringify([recent.id,recent.status,recent.filledUnits]):'';if(recent&&sig!==feedbackSignature&&recent.status!=='pending')$('orderFeedback').textContent='#'+recent.id+' '+recent.side.toUpperCase()+': '+recent.filledUnits+' filled, '+(recent.units-recent.filledUnits)+' unfilled. '+decisionStatus(recent,a);feedbackSignature=sig;
 if(drawn!==a.index)draw();
 if(s.done&&!settled){settled=true;setNotice(explanation(a));try{localStorage.setItem('market-endgames-public-'+session.chapter.id,JSON.stringify(outcome(a)));}catch{}}
}
async function readPackage(url){activeLoad?.abort();const ctrl=new AbortController();activeLoad=ctrl;const timer=setTimeout(()=>ctrl.abort(),20000);try{const res=await fetch(url,{signal:ctrl.signal});if(!res.ok)throw Error('Historical package unavailable');return await res.json();}catch(e){if(e.name==='AbortError')throw Error('Loading timed out or was cancelled. Retry loading to continue.');throw e;}finally{clearTimeout(timer);if(activeLoad===ctrl)activeLoad=null;}}
async function selectChapter(c){if(session&&!session.account.done)session.setPaused(true);const request=++loading;selected=c;$('attemptMode').disabled=false;$('start').disabled=true;$('start').textContent='Checking historical observations…';$('briefDetails').textContent=c.brief;revision=null;
 for(const b of $('choices').children)b.setAttribute('aria-pressed',String(b.dataset.id===c.id));
 try{const data=await readPackage('data/'+c.file);await validateTapePackage(c,data);if(request!==loading)return;source=data;feedbackSignature='';$('orderFeedback').textContent='No orders yet.';$('orderError').hidden=true;$('quantity').value=String(Math.max(c.rules.lotSizeUnits||1,Math.min(10,c.rules.initialUnits)));$('kind').value='market';$('trigger').value='';$('triggerLabel').hidden=true;session=createSession(c,data.rows,render,data.context?.rows||[]);wall.anchor=performance.now();wall.budget=0;drawn=-1;settled=false;setPriceView(c.rules.marketDataKind!=='quote'?'line':60);timingBrief();
 $('symbol').textContent=(c.displaySymbol||c.instrument.symbol+' / '+c.instrument.quote);$('venue').textContent=c.instrument.venue+' · '+c.date;$('mandate').textContent=c.brief;
 $('rulesText').textContent=c.brief;$('provenance').textContent=data.rows.length+' retained observations · '+data.sampling+' Source SHA-256 '+data.sourceSha256;
 $('briefDetails').replaceChildren();const p=document.createElement('p');p.textContent=c.brief;const strong=document.createElement('strong');strong.textContent='Start '+usd(c.rules.initialEquity/100)+' · '+c.rules.initialUnits+' '+c.instrument.base+' · '+utc(data.rows[0][0])+'–'+utc(data.rows.at(-1)[0])+' '+(c.clockZoneLabel||'UTC');$('briefDetails').append(strong,p);
 $('backToAccount').hidden=!briefReturn;$('start').disabled=false;$('start').textContent='Take over the account';setNotice('Ready. The clock starts when you take over.');render();priceChart.timeScale().fitContent();
 }catch(e){if(request!==loading)return;$('start').textContent='Retry loading';$('start').disabled=false;$('briefDetails').textContent=e.message+' No synthetic fallback is used.';session=null;setNotice(e.message);}
}
function showBriefAccount(){if(!session)return;const c=session.chapter;for(const b of $('choices').children)b.setAttribute('aria-pressed',String(b.dataset.id===c.id));$('briefDetails').replaceChildren();const p=document.createElement('p');p.textContent=c.brief;const strong=document.createElement('strong');strong.textContent='Start '+usd(c.rules.initialEquity/100)+' · '+c.rules.initialUnits+' '+c.instrument.base+' · '+utc(source.rows[0][0])+'–'+utc(source.rows.at(-1)[0])+' '+(c.clockZoneLabel||'UTC');$('briefDetails').append(strong,p);}
function openBrief(){syncNow();if(session?.account.practice.mode==='timed'&&!session.account.done)return;$('attemptMode').disabled=!!session&&!session.account.done&&session.account.practice.events.some(e=>e.action==='resume');if(session){briefReturn={session,source,selected,ticket:{quantity:$('quantity').value,kind:$('kind').value,trigger:$('trigger').value,error:$('orderError').textContent,errorHidden:$('orderError').hidden}};showBriefAccount();}if(session&&!session.account.done){session.setPaused(true);$('backToAccount').hidden=false;$('start').textContent='Resume current account';}else if(session?.account.done){$('backToAccount').hidden=false;$('start').textContent='Restart selected challenge';}$('brief').showModal();}
function execute(side){try{syncNow();const signature=[side,$('quantity').value,$('kind').value,$('trigger').value].join('|'),now=performance.now();if(signature===lastOrderSignature&&now-lastOrderClick<500)return;lastOrderClick=now;lastOrderSignature=signature;if(!session)throw Error('Load a challenge first');const quantity=Number($('quantity').value);if(!$('quantity').value.trim())throw Error('Enter a whole-unit quantity');const kind=$('kind').value,trigger=kind==='stop'?Number($('trigger').value):undefined;const o=session.order(side,quantity,kind,trigger);$('orderError').hidden=true;$('orderFeedback').textContent='Order #'+o.id+' queued. Routing '+session.account.rules.routeDelayMs/1000+' historical seconds, then waiting for a subsequent source observation.';}catch(e){$('orderError').textContent=e.message;$('orderError').hidden=false;}}
$('buy').onclick=()=>execute('buy');$('sell').onclick=()=>execute('sell');$('half').onclick=()=>{syncNow();const lot=session?.account.rules.lotSizeUnits||1;$('quantity').value=Math.max(lot,Math.floor((session?.account.units||0)/2/lot)*lot);render();};$('all').onclick=()=>{syncNow();$('quantity').value=session?.account.units||session?.account.rules.lotSizeUnits||1;render();};$('quantity').oninput=render;$('kind').onchange=()=>{$('triggerLabel').hidden=$('kind').value!=='stop';render();};
$('pause').onclick=()=>{syncNow();session?.setPaused(!session.paused);};$('speed').onchange=()=>{syncNow();session?.setPlayback(Number($('speed').value),false);setNotice('Practice speed '+$('speed').value+'×. Historical quote gaps are preserved.');};
$('choose').onclick=openBrief;function restoreAccount(){loading++;activeLoad?.abort();if(briefReturn){({session,source,selected}=briefReturn);const t=briefReturn.ticket;$('quantity').value=t.quantity;$('kind').value=t.kind;$('trigger').value=t.trigger;$('triggerLabel').hidden=t.kind!=='stop';$('orderError').textContent=t.error;$('orderError').hidden=t.errorHidden;briefReturn=null;drawn=-1;setPriceView(session.account.rules.marketDataKind!=='quote'?'line':60);render();}$('brief').close();}$('backToAccount').onclick=restoreAccount;$('brief').addEventListener('cancel',()=>{loading++;activeLoad?.abort();if(briefReturn){({session,source,selected}=briefReturn);const t=briefReturn.ticket;$('quantity').value=t.quantity;$('kind').value=t.kind;$('trigger').value=t.trigger;$('triggerLabel').hidden=t.kind!=='stop';$('orderError').textContent=t.error;$('orderError').hidden=t.errorHidden;briefReturn=null;drawn=-1;setPriceView(session.account.rules.marketDataKind!=='quote'?'line':60);render();}});$('start').onclick=async()=>{if(!session){selectChapter(selected);return;}if(session.account.done)await selectChapter(selected);if(!session)return;if(briefReturn?.session===session&&!session.account.done&&session.account.practice.events.some(e=>e.action==='resume')){briefReturn=null;$('brief').close();syncNow();session.setPaused(false);setNotice('Resumed the same practice account; orders and elapsed history retained.');return;}briefReturn=null;$('brief').close();const timed=$('attemptMode').value==='timed';const c=selected;const timing=timed?{mode:'timed',speed:c.timedSpeed||12}:null;session=createSession({...c,timing,rules:{...c.rules,routeDelayMs:timed?(c.timedRouteDelayMs||6000):0}},source.rows,render,source.context?.rows||[]);wall.anchor=performance.now();wall.budget=0;drawn=-1;settled=false;$('speed').value=String(timing?.speed||Number($('speed').value));session.setPlayback(Number($('speed').value),false);session.setPaused(false);setNotice('The market clock is running. Submission is not a guaranteed fill; subsequent observations determine the result.');};
$('attemptMode').onchange=timingBrief;$('sourceBtn').onclick=()=>{syncNow();$('rules').showModal();};for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{syncNow();setPriceView(b.dataset.view==='line'?'line':Number(b.dataset.view));draw();priceChart.timeScale().fitContent();};$('latest').onclick=()=>{syncNow();priceChart.timeScale().fitContent();};
function invalidate(){revision=null;$('comparison').replaceChildren();$('comparisonStatus').textContent='Inputs changed. Compare again to recalculate.';$('download').textContent='Download original report';$('record').textContent=JSON.stringify({chapter:session.chapter.id,original:session.account},null,2);drawReview();}
$('reviewBtn').onclick=()=>{if(!session?.account.done)return;$('originalResult').textContent='Original: '+(outcome(session.account).passed?'mandate met':'mandate missed')+' · '+usd(session.snapshot().equity)+'. '+explanation(session.account);
 $('edits').replaceChildren(...session.account.orders.filter(o=>!o.automatic).map(o=>{const d=document.createElement('div');d.className='edit';const label=document.createElement('label');label.textContent='#'+o.id+' · '+utc(o.time)+' '+(session.chapter.clockZoneLabel||'UTC')+' '+o.side+' · original '+o.units;const input=document.createElement('input');input.type='number';input.step=String(session.account.rules.lotSizeUnits||1);input.min='0';input.value=o.units;input.dataset.id=o.id;input.setAttribute('aria-label','Revised quantity for order '+o.id);input.oninput=invalidate;d.append(label,input);for(const [name,n] of [['Skip',0],['Restore',o.units]]){const b=document.createElement('button');b.textContent=name;b.onclick=()=>{input.value=n;invalidate();};d.append(b);}return d;}));
 $('compare').disabled=!session.account.orders.some(o=>!o.automatic);$('review').showModal();invalidate();$('comparisonStatus').textContent='Original account shown. Change up to two decisions or compare unchanged.';};
$('compare').onclick=()=>{try{const inputs=Object.fromEntries([...$('edits').querySelectorAll('input')].map(i=>[i.dataset.id,i.value]));const changes=revisionChanges(session.account,inputs);revision=session.revise(changes);const c=compareAccounts(session.account,revision),a=session.account;
 $('comparisonStatus').textContent=c.changed.length+' of 2 decisions changed. Original '+(c.original.passed?'met':'missed')+' → revised '+(c.revised.passed?'met':'missed')+' the mandate. Original saved result unchanged.';const box=$('comparison');box.replaceChildren();const table=document.createElement('table');
 for(const row of [['At close','Original','Revised'],['Equity',usd(c.original.equity/100),usd(c.revised.equity/100)],['Cash',usd(a.cash/100),usd(revision.cash/100)],['Marked position',usd((c.original.equity-a.cash)/100),usd((c.revised.equity-revision.cash)/100)],['Fees',usd(a.fees/100),usd(revision.fees/100)],['Units held · '+session.instrument.base,String(a.units),String(revision.units)]]){const tr=document.createElement('tr');row.forEach((s,i)=>{const td=document.createElement(i?'td':'th');td.textContent=s;tr.append(td);});table.append(tr);}box.append(table);
 const add=s=>{const p=document.createElement('p');p.textContent=s;box.append(p);};add(explanation(revision));add('Equity change '+usd(c.equityDelta/100)+' = cash change '+usd(c.cashDelta/100)+' + marked-position change '+usd(c.positionDelta/100)+'. Fees are already included in cash.');for(const {original:o,revised:n} of c.affected)add('Order #'+o.id+(o.units!==n.units?' edited':' affected by earlier decisions')+': requested '+o.units+' → '+n.units+'; filled '+o.filledUnits+' → '+n.filledUnits+'. '+decisionStatus(o,a)+' → '+decisionStatus(n,revision)+'.');add('Changes act together, not as independent profit contributions. Original close '+utc(a.time)+'; revised close '+utc(revision.time)+' '+(session.chapter.clockZoneLabel||'UTC')+'. Repeated play is known-history practice, not evidence of trading skill.');
 $('download').textContent='Download comparison report';$('record').textContent=JSON.stringify({chapter:session.chapter.id,changes,original:a,revised:revision},null,2);drawReview();
 }catch(e){invalidate();$('comparisonStatus').textContent=e.message;}};
$('download').onclick=()=>{const b=new Blob([buildReport(session.chapter,source,session.account,revision)],{type:'text/plain'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=session.chapter.id+'-review.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.addEventListener('visibilitychange',()=>{syncNow();if(document.hidden&&session&&!session.account.done){session.setPaused(true,'Tab hidden');setNotice('Interrupted when this tab was hidden. Resume explicitly; the interruption is recorded and this becomes an assisted result.');}});
function frame(){syncNow(false);requestAnimationFrame(frame);}requestAnimationFrame(frame);
try{catalog=await readPackage('data/chapters.json');$('choices').replaceChildren(...catalog.map(c=>{const b=document.createElement('button');b.className='choice';b.dataset.id=c.id;b.textContent=c.title;const small=document.createElement('small');small.textContent=c.instrument.symbol+' · '+c.date+' · '+c.instrument.venue;b.append(small);b.onclick=()=>selectChapter(c);return b;}));openBrief();await selectChapter(catalog[0]);}catch(e){setNotice(e.message+' Reload to retry.');}
